import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CxkNbRKf.js";const m=JSON.parse('{"title":"Installation overview","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/index.md","filePath":"installation-guide/index.md","lastUpdated":1786379412000}'),n={name:"installation-guide/index.md"};function s(i,t,l,d,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="installation-overview" tabindex="-1">Installation overview <a class="header-anchor" href="#installation-overview" aria-label="Permalink to &quot;Installation overview&quot;">​</a></h1><p>NADA is deployed as a <strong>web application</strong> on a server with PHP and a supported database. Choose a platform guide below for complete install instructions. This overview follows the same pattern as the <a href="https://worldbank.github.io/metadata-editor-docs/tech_installation.html" target="_blank" rel="noreferrer">Metadata Editor installation</a>, with NADA-specific options such as <strong>Microsoft SQL Server</strong>.</p><hr><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Requirement</th></tr></thead><tbody><tr><td><strong>CPU</strong></td><td>Dual-core or higher</td></tr><tr><td><strong>RAM</strong></td><td>4 GB minimum; 8 GB+ recommended for larger catalogs</td></tr><tr><td><strong>Storage</strong></td><td>20 GB+ free; catalog files grow under <code>datafiles</code></td></tr><tr><td><strong>Database</strong></td><td><strong>MySQL 8.x</strong> or <strong>MariaDB 10.x+</strong>, <em>or</em> <strong>Microsoft SQL Server</strong> 2012+ with full-text (<strong>pick one</strong>)</td></tr><tr><td><strong>PHP</strong></td><td><strong>7.4</strong> minimum; <strong>PHP 8.x recommended</strong>. Extensions: <code>xsl</code>, <code>xml</code>, <code>mbstring</code>, plus <code>mysqli</code> (MySQL/MariaDB) <strong>or</strong> <code>sqlsrv</code> (SQL Server)</td></tr><tr><td><strong>Web server</strong></td><td>Apache 2.4+, NGINX, or IIS 10+</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Recommended</p><p>New installs should use <strong>PHP 8.x</strong> and <strong>MySQL 8.x</strong> or <strong>MariaDB 10.x+</strong>. PHP 7.4 remains the minimum supported version. MySQL 5.7 and older are not recommended.</p></div><hr><h2 id="choose-your-installation-path" tabindex="-1">Choose your installation path <a class="header-anchor" href="#choose-your-installation-path" aria-label="Permalink to &quot;Choose your installation path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Linux server</strong> (Apache or NGINX)</td><td><a href="./platform-linux.html">Installation (Linux)</a></td></tr><tr><td><strong>Windows server</strong> (IIS)</td><td><a href="./platform-windows.html">Installation (Windows)</a></td></tr><tr><td><strong>Git + Composer</strong></td><td><a href="./installation-git.html">Install with Git</a> (then finish with your platform guide)</td></tr><tr><td><strong>Docker</strong></td><td><a href="./installation-docker.html">Install with Docker</a></td></tr><tr><td><strong>Upgrade an existing install</strong></td><td><a href="./upgrade/">Upgrading</a></td></tr></tbody></table><p>Linux and Windows installs differ substantially (packages vs PHP Manager/IIS, permissions, web server config). Use the platform guide for your OS — do not mix steps from both.</p><hr><h2 id="standard-folder-layout" tabindex="-1">Standard folder layout <a class="header-anchor" href="#standard-folder-layout" aria-label="Permalink to &quot;Standard folder layout&quot;">​</a></h2><p>The web server document root must point at the NADA <strong>application root</strong> (the folder that contains <code>index.php</code>).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nada/                    ← application root (contains index.php)</span></span>
<span class="line"><span>├── application/</span></span>
<span class="line"><span>├── datafiles/           ← catalog data (writable)</span></span>
<span class="line"><span>├── files/               ← sessions, thumbnails, temp (writable)</span></span>
<span class="line"><span>├── logs/                ← logs (writable)</span></span>
<span class="line"><span>├── themes/</span></span>
<span class="line"><span>└── …</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Platform</th><th>Example path</th></tr></thead><tbody><tr><td>Linux</td><td><code>/var/www/nada</code> or <code>/var/www/html/nada</code></td></tr><tr><td>Windows (IIS)</td><td><code>C:\\inetpub\\wwwroot\\nada</code></td></tr></tbody></table><p>Source: <a href="https://github.com/ihsn/nada" target="_blank" rel="noreferrer">https://github.com/ihsn/nada</a> — prefer <a href="https://github.com/ihsn/nada/releases" target="_blank" rel="noreferrer">tagged releases</a> for production.</p><div class="tip custom-block"><p class="custom-block-title">NOTE</p><p>The folder name often becomes part of the catalog URL (for example <code>data</code>, <code>microdata</code>, or <code>catalog</code>).</p></div><hr><h2 id="installation-checklist" tabindex="-1">Installation checklist <a class="header-anchor" href="#installation-checklist" aria-label="Permalink to &quot;Installation checklist&quot;">​</a></h2><ol><li>Follow <strong><a href="./platform-linux.html">Linux</a></strong> or <strong><a href="./platform-windows.html">Windows</a></strong> through stack install, download, database, permissions, web server, and installer.</li><li>Complete <a href="./configurations/">Configurations</a> — especially <a href="./configurations/email.html">email</a>.</li><li><em>(Optional)</em> <a href="./installation-solr.html">Solr</a>, clean URLs, CSP, themes.</li><li><em>(Production)</em> Harden credentials; move <code>datafiles</code> outside the web root when possible; plan backups.</li><li>Continue with <a href="/nada-documentation/getting-started/">Getting started</a>.</li></ol><hr><h2 id="database-options" tabindex="-1">Database options <a class="header-anchor" href="#database-options" aria-label="Permalink to &quot;Database options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Database</th><th>Documentation</th></tr></thead><tbody><tr><td><strong>MySQL 8.x</strong> or <strong>MariaDB 10.x+</strong></td><td>Covered in each platform guide · also <a href="./database-mysql.html">MySQL / MariaDB</a></td></tr><tr><td><strong>Microsoft SQL Server</strong></td><td><a href="./installation-sqlsrv.html">Install with SQL Server</a> (common on Windows)</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="./platform-linux.html">Installation (Linux)</a> · <a href="./platform-windows.html">Installation (Windows)</a></li><li><a href="./php-settings.html">PHP settings</a> · <a href="./database-mysql.html">MySQL / MariaDB</a> · <a href="./installation-sqlsrv.html">SQL Server</a></li><li><a href="./configurations/">Configurations</a> · <a href="./upgrade/">Upgrading</a> · <a href="./debug.html">Debug</a></li><li><a href="/nada-documentation/getting-started/">Getting started</a> · <a href="/nada-documentation/api-guide/">API guide</a></li></ul><p>Metadata Editor (companion tool): <a href="https://worldbank.github.io/metadata-editor-docs/tech_installation.html" target="_blank" rel="noreferrer">Installation overview</a></p>`,27)])])}const g=a(n,[["render",s]]);export{m as __pageData,g as default};
